package com.opensocket.aievent.core.analytics.runtime;
import java.time.Duration;import java.util.Set;import org.springframework.core.env.Environment;import org.springframework.stereotype.Component;import com.opensocket.aievent.core.configuration.runtime.*;
@Component public final class AnalyticsRuntimeConfigurationView {
 public static final String SET_KEY=RuntimeConfigurationSetKeys.ANALYTICS_SYSTEM; public static final String ENABLED="opendispatch.analytics.projection.enabled",BATCH="opendispatch.analytics.projection.batch-size",POLL="opendispatch.analytics.projection.poll-ms",ROLLUP="opendispatch.analytics.rollup.batch-size"; public static final Set<String> ALL=Set.of(ENABLED,BATCH,POLL,ROLLUP);
 private final RuntimeConfigurationSnapshotValues values;private final RuntimeConfigurationAuthorityRegistry authority;private final Environment startup;public AnalyticsRuntimeConfigurationView(RuntimeConfigurationSnapshotValues v,RuntimeConfigurationAuthorityRegistry a,Environment s){values=v;authority=a;startup=s;}
 public boolean enabled(){return bool(ENABLED,true);} public int batchSize(){return integer(BATCH,250,1,1000);} public Duration pollDelay(){return millis(POLL,5000,100,3600000);} public int rollupBatchSize(){return integer(ROLLUP,48,1,500);}
 private boolean bool(String k,boolean f){if(req(k)){snap();return values.booleanValue(SET_KEY,k).orElseThrow(()->inc(k));}return values.booleanValue(SET_KEY,k).orElse(startup.getProperty(k,Boolean.class,f));} private int integer(String k,int f,int min,int max){long v=req(k)?requiredLong(k):values.longValue(SET_KEY,k).orElse(startup.getProperty(k,Long.class,(long)f));if(v<min||v>max)throw bad(k,v);return Math.toIntExact(v);} private Duration millis(String k,long f,long min,long max){long v=req(k)?requiredLong(k):values.longValue(SET_KEY,k).orElse(startup.getProperty(k,Long.class,f));if(v<min||v>max)throw bad(k,v);return Duration.ofMillis(v);} private long requiredLong(String k){snap();return values.longValue(SET_KEY,k).orElseThrow(()->inc(k));} private boolean req(String k){return authority!=null&&authority.isRuntimeAuthoritative(k);} private void snap(){if(!values.hasSnapshot(SET_KEY))throw inc("*");values.requireKeys(SET_KEY,ALL);} private static IllegalStateException bad(String k,Object v){return new IllegalStateException("RUNTIME_CONFIG_VALIDATION_FAILED key="+k+" value="+v);} private static IllegalStateException inc(String k){return new IllegalStateException("CONFIGURATION_INCOMPLETE setKey="+SET_KEY+" key="+k);}
}
